package com.example.fsmstudio;
import android.content.*;import android.graphics.*;import android.view.*;
public class GraphView extends View {
 public interface Listener {void selected(Model.State state);void changed();}
 public Model model;public Model.State selected;public String activeId="";public Listener listener;private Paint p=new Paint(3);private float panX=90,panY=65,scale=1,downX,downY,lastX,lastY;private Model.State drag;private boolean moved=false,linkMode=false;private ScaleGestureDetector pinch;
 private final float W=174,H=76;
 public GraphView(Context c,Model m){super(c);model=m;setBackgroundColor(0xff161c27);pinch=new ScaleGestureDetector(c,new ScaleGestureDetector.SimpleOnScaleGestureListener(){public boolean onScale(ScaleGestureDetector d){float old=scale;scale=Math.max(.3f,Math.min(3f,scale*d.getScaleFactor()));panX=d.getFocusX()-(d.getFocusX()-panX)*scale/old;panY=d.getFocusY()-(d.getFocusY()-panY)*scale/old;invalidate();return true;}});}
 public void connectMode(){linkMode=true;}
 public void resetView(){scale=1;panX=90;panY=65;invalidate();}
 private void color(int c){p.setColor(c);p.setStyle(Paint.Style.FILL);p.setStrokeWidth(1);}
 private void line(Canvas c,float a,float b,float d,float e,int color,float width){color(color);p.setStrokeWidth(width);c.drawLine(a,b,d,e,p);}
 private void text(Canvas c,String s,float x,float y,int size,int color){color(color);p.setTextSize(size);c.drawText(s,x,y,p);}
 @Override protected void onDraw(Canvas c){super.onDraw(c);c.drawColor(0xff161c27);c.save();c.translate(panX,panY);c.scale(scale,scale);Rect clip=c.getClipBounds();float l=(-panX)/scale-80,t=(-panY)/scale-80,r=(getWidth()-panX)/scale+80,b=(getHeight()-panY)/scale+80;for(int x=(int)Math.floor(l/40)*40;x<r;x+=40)line(c,x,t,x,b,0xff283141,1);for(int y=(int)Math.floor(t/40)*40;y<b;y+=40)line(c,l,y,r,y,0xff283141,1);
 for(Model.Edge e:model.edges){Model.State a=model.get(e.from),z=model.get(e.to);if(a==null||z==null)continue;float x1=a.x+W,y1=a.y+H/2,x2=z.x,y2=z.y+H/2;float bend=Math.max(65,Math.abs(x2-x1)*.45f);Path path=new Path();path.moveTo(x1,y1);path.cubicTo(x1+bend,y1,x2-bend,y2,x2,y2);color(0xff79b4ec);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(3);c.drawPath(path,p);p.setStyle(Paint.Style.FILL);Path arrow=new Path();arrow.moveTo(x2,y2);arrow.lineTo(x2-12,y2-7);arrow.lineTo(x2-12,y2+7);arrow.close();c.drawPath(arrow,p);text(c,e.event,(x1+x2)/2-22,(y1+y2)/2-12,11,0xffd3e5f8);}
 for(Model.State s:model.states){color(s==selected?0xfff1c46a:s.id.equals(activeId)?0xff64e2a0:0xff60768e);c.drawRoundRect(s.x-3,s.y-3,s.x+W+3,s.y+H+3,11,11,p);color(s.color);c.drawRoundRect(s.x,s.y,s.x+W,s.y+H,9,9,p);text(c,s.name,s.x+12,s.y+30,17,0xffffffff);text(c,s.start?"START STATE":"FSM STATE",s.x+12,s.y+54,11,0xffb4c4d5);color(0xff6fb0ef);c.drawCircle(s.x+W,s.y+H/2,7,p);}
 c.restore();}
 private Model.State hit(float x,float y){for(int i=model.states.size()-1;i>=0;i--){Model.State s=model.states.get(i);if(x>=s.x&&x<=s.x+W&&y>=s.y&&y<=s.y+H)return s;}return null;}
 @Override public boolean onTouchEvent(android.view.MotionEvent e){pinch.onTouchEvent(e);if(e.getPointerCount()>1){drag=null;return true;}float x=(e.getX()-panX)/scale,y=(e.getY()-panY)/scale;switch(e.getActionMasked()){case MotionEvent.ACTION_DOWN:downX=x;downY=y;lastX=e.getX();lastY=e.getY();moved=false;drag=hit(x,y);if(linkMode&&selected!=null&&drag!=null&&drag!=selected){Model.Edge edge=new Model.Edge(selected.id,drag.id);model.edges.add(edge);linkMode=false;if(listener!=null)listener.changed();invalidate();return true;}if(drag!=null){selected=drag;if(listener!=null)listener.selected(selected);}invalidate();return true;
 case MotionEvent.ACTION_MOVE:if(pinch.isInProgress())return true;if(Math.abs(x-downX)+Math.abs(y-downY)>4)moved=true;if(drag!=null){drag.x+=(e.getX()-lastX)/scale;drag.y+=(e.getY()-lastY)/scale;}else{panX+=e.getX()-lastX;panY+=e.getY()-lastY;}lastX=e.getX();lastY=e.getY();invalidate();return true;
 case MotionEvent.ACTION_UP:if(drag!=null&&moved){drag.x=Math.round(drag.x/20)*20;drag.y=Math.round(drag.y/20)*20;if(listener!=null)listener.changed();}drag=null;return true;}return true;}
 public void addState(){selected=model.add((getWidth()/2f-panX)/scale,(getHeight()/2f-panY)/scale);if(listener!=null){listener.selected(selected);listener.changed();}invalidate();}
}